package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DeriveMetricsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property derive metrics of observed source ")
  void test_derive_metrics_v_o_builder() {
    Assertions.assertFalse(DeriveMetricsVO.nullValue().isDeriveMetrics(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DeriveMetricsVO.tryFrom(null).isDeriveMetrics(),
        "With a null value, no present result");
    Assertions.assertEquals(true, DeriveMetricsVO.from(true).isDeriveMetrics());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DeriveMetricsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", DeriveMetricsVO.from(true).toString());
  }
}
